166	type WorkspaceMode = "desk" | "room";
167	type WorkspaceTextField =
168	  | "activeLessonId"
169	  | "noteText"
170	  | "answer"
171	  | "comment"
172	  | "materialTitle"
173	  | "materialUrl"
174	  | "cardFront"
175	  | "cardBack";
176	
177	interface CourseWorkspaceState {
178	  snapshot: CourseViewerSnapshot | null;
179	  loading: boolean;
180	  error: string;
181	  saving: string;
182	  mode: WorkspaceMode;
183	  activeLessonId: string;
184	  noteText: string;
185	  answer: string;
186	  shareAnswer: boolean;
187	  comment: string;
188	  inviteOpen: boolean;
189	  materialTitle: string;
190	  materialUrl: string;
191	  cardFront: string;
192	  cardBack: string;
193	}
194	
195	type CourseWorkspaceAction =
196	  | { type: "snapshot.received"; snapshot: CourseViewerSnapshot }
197	  | { type: "loading.finished" }
198	  | { type: "error.changed"; message: string }
199	  | { type: "saving.changed"; label: string }
200	  | { type: "mode.changed"; mode: WorkspaceMode }
201	  | { type: "text.changed"; field: WorkspaceTextField; value: string }
202	  | { type: "note.synced"; noteText: string }
203	  | { type: "answer.synced"; answer: string; shareAnswer: boolean }
204	  | { type: "share-answer.changed"; value: boolean }
205	  | { type: "invite.changed"; open: boolean }
206	  | { type: "material.cleared" }
207	  | { type: "card.cleared" };
208	
209	const INITIAL_WORKSPACE_STATE: CourseWorkspaceState = {
210	  snapshot: null,
211	  loading: true,
212	  error: "",
213	  saving: "",
214	  mode: "desk",
215	  activeLessonId: "",
216	  noteText: "",
217	  answer: "",
218	  shareAnswer: false,
219	  comment: "",
220	  inviteOpen: false,
221	  materialTitle: "",
222	  materialUrl: "",
223	  cardFront: "",
224	  cardBack: "",
225	};
226	
227	function courseWorkspaceReducer(
228	  state: CourseWorkspaceState,
229	  action: CourseWorkspaceAction,
230	): CourseWorkspaceState {
231	  switch (action.type) {
232	    case "snapshot.received":
233	      return { ...state, snapshot: action.snapshot, error: "" };
234	    case "loading.finished":
235	      return state.loading ? { ...state, loading: false } : state;
236	    case "error.changed":
237	      return state.error === action.message
238	        ? state
239	        : { ...state, error: action.message };
240	    case "saving.changed":
241	      return state.saving === action.label
242	        ? state
243	        : { ...state, saving: action.label };
244	    case "mode.changed":
245	      return state.mode === action.mode
246	        ? state
247	        : { ...state, mode: action.mode };
248	    case "text.changed":
249	      return state[action.field] === action.value
250	        ? state
251	        : { ...state, [action.field]: action.value };
252	    case "note.synced":
253	      return state.noteText === action.noteText
254	        ? state
255	        : { ...state, noteText: action.noteText };
256	    case "answer.synced":
257	      return {
258	        ...state,
259	        answer: action.answer,
260	        shareAnswer: action.shareAnswer,
261	      };
262	    case "share-answer.changed":
263	      return state.shareAnswer === action.value
264	        ? state
265	        : { ...state, shareAnswer: action.value };
266	    case "invite.changed":
267	      return state.inviteOpen === action.open
268	        ? state
269	        : { ...state, inviteOpen: action.open };
270	    case "material.cleared":
271	      return { ...state, materialTitle: "", materialUrl: "" };
272	    case "card.cleared":
273	      return { ...state, cardFront: "", cardBack: "" };
274	  }
275	}
