function formatRelative(iso: string): string {
  const minutes = Math.max(
    0,
    Math.round((Date.now() - Date.parse(iso)) / 60_000),
  );
  if (minutes < 1) return "now";
  if (minutes < 60) return `${minutes}m`;
  if (minutes < 1_440) return `${Math.round(minutes / 60)}h`;
  return `${Math.round(minutes / 1_440)}d`;
}

function memberName(member: CourseMember, viewerId: string): string {
  return member.accountId === viewerId ? "You" : member.displayName;
}

type WorkspaceMode = "desk" | "room";
type WorkspaceTextField =
  | "activeLessonId"
  | "noteText"
  | "answer"
  | "comment"
  | "materialTitle"
  | "materialUrl"
  | "cardFront"
  | "cardBack";

interface CourseWorkspaceState {
  snapshot: CourseViewerSnapshot | null;
  loading: boolean;
  error: string;
  saving: string;
  mode: WorkspaceMode;
  activeLessonId: string;
  noteText: string;
  answer: string;
  shareAnswer: boolean;
  comment: string;
  inviteOpen: boolean;
  materialTitle: string;
  materialUrl: string;
  cardFront: string;
  cardBack: string;
}

type CourseWorkspaceAction =
  | { type: "snapshot.received"; snapshot: CourseViewerSnapshot }
  | { type: "loading.finished" }
  | { type: "error.changed"; message: string }
  | { type: "saving.changed"; label: string }
  | { type: "mode.changed"; mode: WorkspaceMode }
  | { type: "text.changed"; field: WorkspaceTextField; value: string }
  | { type: "note.synced"; noteText: string }
  | { type: "answer.synced"; answer: string; shareAnswer: boolean }
  | { type: "share-answer.changed"; value: boolean }
  | { type: "invite.changed"; open: boolean }
  | { type: "material.cleared" }
  | { type: "card.cleared" };

const INITIAL_WORKSPACE_STATE: CourseWorkspaceState = {
  snapshot: null,
  loading: true,
  error: "",
  saving: "",
  mode: "desk",
  activeLessonId: "",
  noteText: "",
  answer: "",
  shareAnswer: false,
  comment: "",
  inviteOpen: false,
  materialTitle: "",
  materialUrl: "",
  cardFront: "",
  cardBack: "",
};

function courseWorkspaceReducer(
  state: CourseWorkspaceState,
  action: CourseWorkspaceAction,
): CourseWorkspaceState {
  switch (action.type) {
    case "snapshot.received":
      return { ...state, snapshot: action.snapshot, error: "" };
    case "loading.finished":
      return state.loading ? { ...state, loading: false } : state;
    case "error.changed":
      return state.error === action.message
        ? state
        : { ...state, error: action.message };
    case "saving.changed":
      return state.saving === action.label
        ? state
        : { ...state, saving: action.label };
    case "mode.changed":
      return state.mode === action.mode
        ? state
        : { ...state, mode: action.mode };
    case "text.changed":
      return state[action.field] === action.value
        ? state
        : { ...state, [action.field]: action.value };
    case "note.synced":
      return state.noteText === action.noteText
        ? state
        : { ...state, noteText: action.noteText };
    case "answer.synced":
      return {
        ...state,
        answer: action.answer,
        shareAnswer: action.shareAnswer,
      };
    case "share-answer.changed":
      return state.shareAnswer === action.value
        ? state
        : { ...state, shareAnswer: action.value };
    case "invite.changed":
      return state.inviteOpen === action.open
        ? state
        : { ...state, inviteOpen: action.open };
    case "material.cleared":
      return { ...state, materialTitle: "", materialUrl: "" };
    case "card.cleared":
      return { ...state, cardFront: "", cardBack: "" };
  }
}

export function CourseWorkspace() {
  const { courseId } = useParams({ strict: false }) as { courseId: string };
  const [access, retryAccess] = useCoursesAccess();
  const [state, dispatch] = useReducer(
    courseWorkspaceReducer,
    INITIAL_WORKSPACE_STATE,
  );
  const {
    snapshot,
    loading,
    error,
    saving,
    mode,
    activeLessonId,
    noteText,
    answer,
    shareAnswer,
    comment,
    inviteOpen,
    materialTitle,
    materialUrl,
    cardFront,
    cardBack,
  } = state;
  const setSnapshot = useCallback((next: CourseViewerSnapshot) => {
    dispatch({
      type: "snapshot.received",
      snapshot: normalizeCourseViewerSnapshot(next),
    });
  }, []);
  const setText = useCallback((field: WorkspaceTextField, value: string) => {
    dispatch({ type: "text.changed", field, value });
  }, []);

  const refresh = useCallback(async () => {
    if (access.status !== "ready") return;
    try {
      const next = await getCourse(courseId);
      setSnapshot(next);
    } catch (cause) {
      dispatch({
        type: "error.changed",
        message:
          cause instanceof Error
            ? cause.message
            : "The course could not be loaded.",
      });
    } finally {
      dispatch({ type: "loading.finished" });
    }
  }, [access.status, courseId, setSnapshot]);

  useEffect(() => {
    void refresh();
  }, [refresh]);
  const realtime = useCourseRealtime(
    access.status === "ready" ? courseId : null,
    setSnapshot,
    () => void refresh(),
  );
  const course = snapshot?.course;
  const lessons = useMemo(
    () => (course ? allCourseLessons(course) : []),
    [course],
  );
  const activeLesson =
    lessons.find((lesson) => lesson.id === activeLessonId) ?? lessons[0];
  const activeModule = course?.modules.find((module) =>
    module.lessons.some((lesson) => lesson.id === activeLesson?.id),
  );
  const sharedNote = course?.sharedNotes.find(
    (note) => note.lessonId === activeLesson?.id,
  );
  const ownSubmission = course?.submissions.find(
    (submission) =>
      submission.lessonId === activeLesson?.id &&
      submission.accountId === snapshot?.viewer.accountId,
  );
  const lessonArtifacts =
    course?.artifacts.filter(
      (artifact) => artifact.lessonId === activeLesson?.id,
    ) ?? [];
  const courseArtifacts =
    course?.artifacts.filter((artifact) => !artifact.lessonId) ?? [];
  const lessonMaterials =
    course?.materials.filter(
      (material) => material.lessonId === activeLesson?.id,
    ) ?? [];
  const lessonAssignments =
    course?.assignments.filter(
      (assignment) => assignment.lessonId === activeLesson?.id,
    ) ?? [];
  const courseAssignments =
    course?.assignments.filter((assignment) => !assignment.lessonId) ?? [];

  useSeo({
    title: course ? `${course.title} — Keating Courses` : "Course — Keating",
    description: course?.description ?? "A collaborative Keating course.",
  });

  useEffect(() => {
    if (!activeLessonId && lessons[0])
      setText(
        "activeLessonId",
        snapshot?.viewer.progress.activeLessonId ?? lessons[0].id,
      );
  }, [
    activeLessonId,
    lessons,
    setText,
    snapshot?.viewer.progress.activeLessonId,
  ]);
  useEffect(() => {
    dispatch({ type: "note.synced", noteText: sharedNote?.text ?? "" });
  }, [sharedNote?.id, sharedNote?.version]);
  useEffect(() => {
    dispatch({
      type: "answer.synced",
      answer: ownSubmission?.answer ?? "",
      shareAnswer: ownSubmission?.sharedWithPeers ?? false,
    });
  }, [ownSubmission?.id, ownSubmission?.version]);

