                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "comment.add",
                    commentId: `comment_${crypto.randomUUID().replaceAll("-", "")}`,
                    lessonId: activeLesson.id,
                    body: comment.trim(),
