type CourseToolsTextField =
  | "courseTitle"
  | "courseDescription"
  | "lessonTitle"
  | "lessonReading";

interface CourseToolsDraft {
  courseTitle: string;
  courseDescription: string;
  lessonTitle: string;
  lessonReading: string;
}

type CourseToolsDraftAction =
  | { type: "course.synced"; title: string; description: string }
  | { type: "lesson.synced"; title: string; reading: string }
  | { type: "text.changed"; field: CourseToolsTextField; value: string };

function courseToolsDraftReducer(
  state: CourseToolsDraft,
  action: CourseToolsDraftAction,
): CourseToolsDraft {
  switch (action.type) {
    case "course.synced":
      return {
        ...state,
        courseTitle: action.title,
        courseDescription: action.description,
      };
    case "lesson.synced":
      return {
        ...state,
        lessonTitle: action.title,
        lessonReading: action.reading,
      };
    case "text.changed":
      return state[action.field] === action.value
        ? state
        : { ...state, [action.field]: action.value };
  }
}

function CourseTools(props: {
  snapshot: CourseViewerSnapshot;
  activeLesson: CourseLesson;
  materialTitle: string;
  setMaterialTitle(value: string): void;
  materialUrl: string;
  setMaterialUrl(value: string): void;
  cardFront: string;
  setCardFront(value: string): void;
  cardBack: string;
  setCardBack(value: string): void;
  saving: string;
  mutate: (
    operation: Parameters<typeof applyCourseOperation>[0],
    label: string,
  ) => Promise<void>;
  onMaterialSaved(): void;
  onCardSaved(): void;
}) {
  const { snapshot, activeLesson } = props;
  const [draft, dispatch] = useReducer(courseToolsDraftReducer, {
    courseTitle: snapshot.course.title,
    courseDescription: snapshot.course.description,
    lessonTitle: activeLesson.title,
    lessonReading: activeLesson.reading,
  });
  const { courseTitle, courseDescription, lessonTitle, lessonReading } = draft;
  useEffect(() => {
    dispatch({
      type: "course.synced",
      title: snapshot.course.title,
      description: snapshot.course.description,
    });
  }, [snapshot.course.title, snapshot.course.description]);
  useEffect(() => {
    dispatch({
      type: "lesson.synced",
      title: activeLesson.title,
      reading: activeLesson.reading,
    });
  }, [activeLesson.id, activeLesson.title, activeLesson.reading]);
  const module = snapshot.course.modules.find((candidate) =>
    candidate.lessons.some((lesson) => lesson.id === activeLesson.id),
  );
  if (!snapshot.permissions.canEditCourse && !snapshot.permissions.canEditDeck)
    return null;
  return (
    <section
      className={css({
        mt: "1.25rem",
        borderTop: "1px solid var(--ink)",
        pt: "1rem",
      })}
    >
      <p className={s.sectionLabel}>Course tools</p>
      {snapshot.permissions.canEditCourse && (
        <>
          <details className={css({ mt: "0.6rem" })}>
            <summary
              className={css({
                cursor: "pointer",
                fontSize: "0.76rem",
                fontWeight: 700,
              })}
            >
              Edit course details
            </summary>
            <div
              className={css({ mt: "0.5rem", display: "grid", gap: "0.4rem" })}
            >
              <input
                value={courseTitle}
                onChange={(event) =>
                  dispatch({
                    type: "text.changed",
                    field: "courseTitle",
                    value: event.target.value,
                  })
                }
                className={s.input}
                placeholder="Course title"
              />
              <textarea
                value={courseDescription}
                onChange={(event) =>
                  dispatch({
                    type: "text.changed",
                    field: "courseDescription",
                    value: event.target.value,
                  })
                }
                className={s.input}
                rows={3}
                placeholder="Course description"
              />
              <button
                type="button"
                className={s.button}
                disabled={!courseTitle.trim() || props.saving === "course"}
                onClick={() =>
                  void props.mutate(
                    {
                      id: newCourseOperationId(),
                      courseId: snapshot.course.id,
                      baseRevision: snapshot.course.revision,
                      type: "course.update",
                      patch: {
                        title: courseTitle,
                        description: courseDescription,
                      },
                    },
                    "course",
                  )
                }
              >
                Save course
              </button>
            </div>
          </details>
          {module && (
            <details className={css({ mt: "0.7rem" })}>
              <summary
                className={css({
                  cursor: "pointer",
                  fontSize: "0.76rem",
                  fontWeight: 700,
                })}
              >
                Edit this lesson
              </summary>
              <div
                className={css({
                  mt: "0.5rem",
                  display: "grid",
                  gap: "0.4rem",
                })}
              >
                <input
                  value={lessonTitle}
                  onChange={(event) =>
                    dispatch({
                      type: "text.changed",
                      field: "lessonTitle",
                      value: event.target.value,
                    })
                  }
                  className={s.input}
                  placeholder="Lesson title"
                />
                <textarea
                  value={lessonReading}
                  onChange={(event) =>
                    dispatch({
                      type: "text.changed",
                      field: "lessonReading",
                      value: event.target.value,
                    })
                  }
                  className={s.input}
                  rows={7}
                  placeholder="Lesson reading"
                />
                <button
                  type="button"
                  className={s.button}
                  disabled={!lessonTitle.trim() || props.saving === "lesson"}
                  onClick={() =>
                    void props.mutate(
                      {
                        id: newCourseOperationId(),
                        courseId: snapshot.course.id,
                        baseRevision: snapshot.course.revision,
                        type: "lesson.update",
                        moduleId: module.id,
                        lesson: {
                          ...activeLesson,
                          title: lessonTitle,
                          reading: lessonReading,
                        },
                      },
                      "lesson",
                    )
                  }
                >
                  Save lesson
                </button>
              </div>
            </details>
          )}
          <details className={css({ mt: "0.7rem" })}>
            <summary
              className={css({
                cursor: "pointer",
                fontSize: "0.76rem",
                fontWeight: 700,
              })}
            >
              Add source link
            </summary>
            <div
              className={css({ mt: "0.5rem", display: "grid", gap: "0.4rem" })}
            >
              <input
                value={props.materialTitle}
                onChange={(event) => props.setMaterialTitle(event.target.value)}
                className={s.input}
                placeholder="Source title"
              />
              <input
                value={props.materialUrl}
                onChange={(event) => props.setMaterialUrl(event.target.value)}
                className={s.input}
                placeholder="https://…"
                type="url"
              />
              <button
                type="button"
                className={s.button}
                disabled={
                  !props.materialTitle ||
                  !props.materialUrl ||
                  props.saving === "material"
                }
                onClick={() =>
                  void props
                    .mutate(
                      {
                        id: newCourseOperationId(),
                        courseId: snapshot.course.id,
                        baseRevision: snapshot.course.revision,
                        type: "material.add",
                        material: {
                          id: `material_${crypto.randomUUID().replaceAll("-", "")}`,
                          kind: "link",
                          title: props.materialTitle,
                          url: props.materialUrl,
                          lessonId: activeLesson.id,
                        },
                      },
                      "material",
                    )
                    .then(props.onMaterialSaved)
                }
              >
                <Plus size={13} /> Add material
              </button>
            </div>
          </details>
        </>
      )}
      {snapshot.permissions.canEditDeck && (
        <details className={css({ mt: "0.7rem" })}>
          <summary
            className={css({
              cursor: "pointer",
              fontSize: "0.76rem",
              fontWeight: 700,
            })}
          >
            Add Anki card
          </summary>
          <div
            className={css({ mt: "0.5rem", display: "grid", gap: "0.4rem" })}
          >
            <textarea
              value={props.cardFront}
              onChange={(event) => props.setCardFront(event.target.value)}
              className={s.input}
              rows={2}
              placeholder="Front"
            />
            <textarea
              value={props.cardBack}
              onChange={(event) => props.setCardBack(event.target.value)}
              className={s.input}
              rows={2}
              placeholder="Back"
            />
            <button
              type="button"
              className={s.button}
              disabled={
                !props.cardFront || !props.cardBack || props.saving === "card"
              }
              onClick={() =>
                void props
                  .mutate(
                    {
                      id: newCourseOperationId(),
                      courseId: snapshot.course.id,
                      baseRevision: snapshot.course.revision,
                      type: "card.upsert",
                      card: {
                        id: `card_${crypto.randomUUID().replaceAll("-", "")}`,
                        front: props.cardFront,
                        back: props.cardBack,
                        tags: [],
                        lessonId: activeLesson.id,
                      },
                    },
                    "card",
                  )
                  .then(props.onCardSaved)
              }
            >
              <Plus size={13} /> Add card
            </button>
          </div>
        </details>
      )}
    </section>
  );
}

