520	    setFront(card.front);
521	    setBack(card.back);
522	    setTags(card.tags.join(", "));
523	    setLessonId(card.lessonId ?? "");
524	  }, [card]);
525	  return (
526	    <details
527	      className={css({ border: "1px solid var(--ink)", bg: "var(--card)" })}
528	    >
529	      <summary
530	        className={css({
531	          cursor: "pointer",
532	          overflow: "hidden",
533	          textOverflow: "ellipsis",
534	          whiteSpace: "nowrap",
535	          px: "0.6rem",
536	          py: "0.5rem",
537	          fontSize: "0.72rem",
538	        })}
539	      >
540	        {card.front}
541	      </summary>
542	      <div
543	        className={css({
544	          display: "grid",
545	          gap: "0.4rem",
546	          borderTop: "1px solid var(--ink)",
547	          p: "0.6rem",
548	        })}
549	      >
550	        <textarea
551	          value={front}
552	          onChange={(event) => setFront(event.target.value)}
553	          className={inputClass}
554	          rows={2}
555	          placeholder="Front"
556	        />
557	        <textarea
558	          value={back}
559	          onChange={(event) => setBack(event.target.value)}
560	          className={inputClass}
561	          rows={3}
562	          placeholder="Back"
563	        />
564	        <input
565	          value={tags}
566	          onChange={(event) => setTags(event.target.value)}
567	          className={inputClass}
568	          placeholder="tags, separated, by commas"
569	        />
570	        <select
571	          value={lessonId}
572	          onChange={(event) => setLessonId(event.target.value)}
573	          className={inputClass}
574	          aria-label="Attach card to lesson"
575	        >
576	          <option value="">Course-wide card</option>
577	          {lessons.map((lesson) => (
578	            <option key={lesson.id} value={lesson.id}>
579	              {lesson.title}
580	            </option>
581	          ))}
582	        </select>
583	        <div
584	          className={css({
585	            display: "flex",
586	            justifyContent: "space-between",
587	            gap: "0.4rem",
588	          })}
589	        >
590	          <button
591	            type="button"
592	            className={buttonClass}
593	            disabled={
594	              !front.trim() || !back.trim() || saving === `card-${card.id}`
595	            }
596	            onClick={() =>
597	              void mutate(
598	                {
599	                  ...operationBase(snapshot),
600	                  type: "card.upsert",
601	                  card: {
602	                    id: card.id,
603	                    front: front.trim(),
604	                    back: back.trim(),
605	                    tags: tags
606	                      .split(",")
607	                      .map((tag) => tag.trim())
608	                      .filter(Boolean)
609	                      .slice(0, 24),
610	                    ...(lessonId ? { lessonId } : {}),
611	                  },
612	                },
613	                `card-${card.id}`,
614	              )
615	            }
616	          >
617	            <Save size={12} /> Save
618	          </button>
619	          <button
620	            type="button"
621	            className={cx(buttonClass, css({ color: "var(--destructive)" }))}
622	            onClick={() => {
623	              if (confirmRemoval("Remove this card?"))
624	                void mutate(
625	                  {
626	                    ...operationBase(snapshot),
627	                    type: "card.delete",
628	                    cardId: card.id,
629	                  },
630	                  `card-delete-${card.id}`,
631	                );
632	            }}
633	          >
634	            <Trash2 size={12} /> Remove
635	          </button>
636	        </div>
637	      </div>
638	    </details>
639	  );
640	}
