642	function DeckManager({
643	  snapshot,
644	  activeLesson,
645	  saving,
646	  mutate,
647	}: {
648	  snapshot: CourseViewerSnapshot;
649	  activeLesson?: CourseLesson;
650	  saving: string;
651	  mutate: Mutate;
652	}) {
653	  const [front, setFront] = useState("");
654	  const [back, setBack] = useState("");
655	  const [decks, setDecks] = useState<FlashcardDeck[]>([]);
656	  const [deckId, setDeckId] = useState("");
657	  const [attachImported, setAttachImported] = useState(Boolean(activeLesson));
658	  useEffect(() => {
659	    let cancelled = false;
660	    void getInitPromise()
661	      .then(() => keatingStorage.getDecks())
662	      .then((items) => {
663	        if (!cancelled) setDecks(items);
664	      })
665	      .catch(() => {});
666	    return () => {
667	      cancelled = true;
668	    };
669	  }, []);
670	  const addCard = async () => {
671	    if (!front.trim() || !back.trim()) return;
672	    await mutate(
673	      {
674	        ...operationBase(snapshot),
675	        type: "card.upsert",
676	        card: {
677	          id: `card_${crypto.randomUUID().replaceAll("-", "")}`,
678	          front: front.trim(),
679	          back: back.trim(),
680	          tags: [],
681	          ...(activeLesson ? { lessonId: activeLesson.id } : {}),
682	        },
683	      },
684	      "card-add",
685	    );
686	    setFront("");
687	    setBack("");
688	  };
689	  const importDeck = () => {
690	    const deck = decks.find((candidate) => candidate.id === deckId);
691	    if (!deck) return;
692	    const cards = assembleCourseInput({ decks: [deck] }).cards.map((card) => ({
693	      ...card,
694	      id: `card_${crypto.randomUUID().replaceAll("-", "")}`,
695	      ...(attachImported && activeLesson ? { lessonId: activeLesson.id } : {}),
696	    }));
697	    void mutate(
698	      { ...operationBase(snapshot), type: "cards.import", cards },
699	      `deck-import-${deck.id}`,
700	    );
701	  };
702	  return (
703	    <div className={css({ display: "grid", gap: "0.55rem" })}>
704	      <div
705	        className={css({
706	          display: "grid",
707	          gap: "0.4rem",
708	          border: "1px solid var(--ink)",
709	          bg: "var(--paper)",
710	          p: "0.6rem",
711	        })}
712	      >
713	        <textarea
714	          value={front}
715	          onChange={(event) => setFront(event.target.value)}
716	          className={inputClass}
717	          rows={2}
718	          placeholder="New card front"
719	        />
720	        <textarea
721	          value={back}
722	          onChange={(event) => setBack(event.target.value)}
723	          className={inputClass}
724	          rows={2}
725	          placeholder="New card back"
726	        />
727	        <button
728	          type="button"
729	          className={buttonClass}
730	          disabled={!front.trim() || !back.trim() || saving === "card-add"}
731	          onClick={() => void addCard()}
732	        >
733	          <Plus size={12} /> Add card{activeLesson ? " to lesson" : ""}
734	        </button>
735	      </div>
736	      {decks.length ? (
737	        <div
738	          className={css({
739	            display: "grid",
740	            gap: "0.4rem",
741	            border: "1px solid var(--ink)",
742	            bg: "var(--paper)",
743	            p: "0.6rem",
744	          })}
745	        >
746	          <select
747	            value={deckId}
748	            onChange={(event) => setDeckId(event.target.value)}
749	            className={inputClass}
750	          >
751	            <option value="">Choose a saved deck…</option>
752	            {decks.map((deck) => (
753	              <option key={deck.id} value={deck.id}>
754	                {deck.title} ({deck.cards.length})
755	              </option>
756	            ))}
757	          </select>
758	          {activeLesson ? (
759	            <label
760	              className={css({
761	                display: "inline-flex",
762	                alignItems: "center",
763	                gap: "0.4rem",
764	                fontSize: "0.7rem",
765	              })}
766	            >
767	              <input
768	                type="checkbox"
769	                checked={attachImported}
770	                onChange={(event) => setAttachImported(event.target.checked)}
771	              />{" "}
772	              Attach imported cards to this lesson
773	            </label>
774	          ) : null}
775	          <button
776	            type="button"
777	            className={buttonClass}
778	            disabled={!deckId || saving.startsWith("deck-import-")}
779	            onClick={importDeck}
780	          >
781	            <Upload size={12} /> Import deck
782	          </button>
783	        </div>
784	      ) : (
785	        <p className={css({ fontSize: "0.7rem", color: "var(--ink-soft)" })}>
786	          No saved decks yet. New cards can still be created here.
787	        </p>
788	      )}
789	      {snapshot.course.cards.length ? (
790	        <div className={css({ display: "grid", gap: "0.4rem" })}>
791	          {snapshot.course.cards.map((card) => (
792	            <CardEditor
793	              key={card.id}
794	              snapshot={snapshot}
795	              card={card}
796	              saving={saving}
797	              mutate={mutate}
798	            />
799	          ))}
800	        </div>
801	      ) : null}
802	    </div>
803	  );
804	}
