900	              onClick={() => void addModule()}
901	            >
902	              <Plus size={12} /> Module
903	            </button>
904	          </div>
905	          <div
906	            className={css({ mt: "0.55rem", display: "grid", gap: "0.4rem" })}
907	          >
908	            {snapshot.course.modules.map((module) => (
909	              <ModuleEditor
910	                key={module.id}
911	                snapshot={snapshot}
912	                module={module}
913	                saving={saving}
914	                mutate={mutate}
915	              />
916	            ))}
917	          </div>
918	          {activeLesson ? (
919	            <div className={sectionClass}>
920	              <LessonEditor
921	                snapshot={snapshot}
922	                lesson={activeLesson}
923	                saving={saving}
924	                mutate={mutate}
925	              />
926	            </div>
927	          ) : null}
928	        </>
929	      ) : null}
930	      {canStructure ? (
