956	              display: "flex",
957	              alignItems: "center",
958	              gap: "0.4rem",
959	              mb: "0.55rem",
960	              fontSize: "0.78rem",
961	              fontWeight: 750,
962	            })}
963	          >
964	            <Shapes size={14} /> Quizzes, GenUI, visuals, and artifacts
965	          </p>
966	          <ArtifactManager
967	            snapshot={snapshot}
