import { useEffect, useMemo, useState } from "react";
import {
  BookUp,
  CreditCard,
  FilePlus2,
  FileQuestion,
  Layers3,
  Plus,
  Save,
  Shapes,
  Trash2,
  Upload,
} from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import { assembleCourseInput } from "../../courses/course-assembly";
import {
  newCourseOperationId,
  type applyCourseOperation,
} from "../../courses/client";
import type {
  CourseCard,
  CourseLesson,
  CourseModule,
  CourseOperation,
  CourseViewerSnapshot,
} from "../../courses/contracts";
import { getInitPromise, keatingStorage } from "../../hooks/keating-storage";
import type { FlashcardDeck } from "../../keating/flashcard-types";
import {
  ArtifactManager,
  AssignmentManager,
  MaterialManager,
} from "./CourseContentManagers";

const inputClass = css({
  w: "100%",
  border: "1px solid var(--ink)",
  bg: "var(--paper)",
  px: "0.65rem",
  py: "0.55rem",
  fontSize: "0.8rem",
  outline: 0,
  _focus: { boxShadow: "0 0 0 2px var(--peer-blue, #3468b3)" },
});
const buttonClass = css({
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  gap: "0.35rem",
  border: "1px solid var(--ink)",
  px: "0.65rem",
  py: "0.45rem",
  fontSize: "0.72rem",
  fontWeight: 750,
  _hover: { bg: "var(--course-wash, #ddebdd)" },
  _disabled: { opacity: 0.55 },
});
const sectionClass = css({
  mt: "1rem",
  borderTop: "1px solid var(--ink)",
  pt: "0.85rem",
});
const labelClass = css({
  fontFamily: "var(--mono-display)",
  fontSize: "0.63rem",
  fontWeight: 700,
  letterSpacing: "0.08em",
  textTransform: "uppercase",
  color: "var(--ink-soft)",
});

type Mutate = (
  operation: Parameters<typeof applyCourseOperation>[0],
  label: string,
) => Promise<void>;

function operationBase(
  snapshot: CourseViewerSnapshot,
): Pick<CourseOperation, "id" | "courseId" | "baseRevision"> {
  return {
    id: newCourseOperationId(),
    courseId: snapshot.course.id,
    baseRevision: snapshot.course.revision,
  };
}

function confirmRemoval(message: string): boolean {
  return typeof window === "undefined" || window.confirm(message);
}

function ModuleEditor({
  snapshot,
  module,
  saving,
  mutate,
}: {
  snapshot: CourseViewerSnapshot;
  module: CourseModule;
  saving: string;
  mutate: Mutate;
}) {
  const [title, setTitle] = useState(module.title);
  const [description, setDescription] = useState(module.description);
  const [lessonTitle, setLessonTitle] = useState("");
  useEffect(() => {
    setTitle(module.title);
    setDescription(module.description);
  }, [module.description, module.title]);

  const saveModule = () =>
    mutate(
      {
        ...operationBase(snapshot),
        type: "module.upsert",
        module: { ...module, title: title.trim(), description },
      },
      `module-${module.id}`,
    );
  const addLesson = async () => {
    if (!lessonTitle.trim()) return;
    await mutate(
      {
        ...operationBase(snapshot),
        type: "lesson.update",
        moduleId: module.id,
        lesson: {
          id: `lesson_${crypto.randomUUID().replaceAll("-", "")}`,
          title: lessonTitle.trim(),
          summary: "",
          objectives: [],
          reading: "",
          materialIds: [],
          cardIds: [],
        },
      },
      `lesson-add-${module.id}`,
    );
    setLessonTitle("");
  };

  return (
    <details
      className={css({ border: "1px solid var(--ink)", bg: "var(--card)" })}
    >
      <summary
        className={css({
          cursor: "pointer",
          px: "0.65rem",
          py: "0.55rem",
          fontSize: "0.78rem",
          fontWeight: 750,
        })}
      >
        {module.title}{" "}
        <span className={css({ color: "var(--ink-soft)", fontWeight: 400 })}>
          · {module.lessons.length} lesson
          {module.lessons.length === 1 ? "" : "s"}
        </span>
      </summary>
      <div
        className={css({
          display: "grid",
          gap: "0.45rem",
          borderTop: "1px solid var(--ink)",
          p: "0.65rem",
        })}
      >
        <input
          value={title}
          maxLength={240}
          onChange={(event) => setTitle(event.target.value)}
          className={inputClass}
          aria-label="Module title"
        />
        <textarea
          value={description}
          maxLength={2_000}
          onChange={(event) => setDescription(event.target.value)}
          className={inputClass}
          rows={2}
          aria-label="Module description"
          placeholder="Module description"
        />
        <div
          className={css({
            display: "flex",
            justifyContent: "space-between",
            gap: "0.4rem",
          })}
        >
          <button
            type="button"
            className={buttonClass}
            disabled={!title.trim() || saving === `module-${module.id}`}
            onClick={() => void saveModule()}
          >
            <Save size={12} /> Save
          </button>
          <button
            type="button"
            className={cx(buttonClass, css({ color: "var(--destructive)" }))}
            onClick={() => {
              if (confirmRemoval(`Remove “${module.title}” and its lessons?`))
                void mutate(
                  {
                    ...operationBase(snapshot),
                    type: "module.delete",
                    moduleId: module.id,
                  },
                  `module-delete-${module.id}`,
                );
            }}
          >
            <Trash2 size={12} /> Remove
          </button>
        </div>
        <div
          className={css({
            mt: "0.25rem",
            display: "flex",
            alignItems: "stretch",
            gap: "0.35rem",
            borderTop: "1px solid var(--border)",
            pt: "0.55rem",
          })}
        >
          <input
            value={lessonTitle}
            maxLength={240}
            onChange={(event) => setLessonTitle(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") void addLesson();
            }}
            className={inputClass}
            placeholder="New lesson title"
            aria-label={`New lesson in ${module.title}`}
          />
          <button
            type="button"
            className={buttonClass}
            disabled={
              !lessonTitle.trim() || saving === `lesson-add-${module.id}`
            }
            onClick={() => void addLesson()}
          >
            <Plus size={12} /> Lesson
          </button>
        </div>
      </div>
    </details>
  );
}

function LessonEditor({
  snapshot,
  lesson,
  saving,
  mutate,
}: {
  snapshot: CourseViewerSnapshot;
  lesson: CourseLesson;
  saving: string;
  mutate: Mutate;
}) {
  const module = snapshot.course.modules.find((candidate) =>
    candidate.lessons.some((item) => item.id === lesson.id),
  );
  const [title, setTitle] = useState(lesson.title);
  const [summary, setSummary] = useState(lesson.summary);
  const [reading, setReading] = useState(lesson.reading);
  const [objectives, setObjectives] = useState(lesson.objectives.join("\n"));
  const [hasQuestion, setHasQuestion] = useState(Boolean(lesson.exercise));
  const [prompt, setPrompt] = useState(lesson.exercise?.prompt ?? "");
  const [placeholder, setPlaceholder] = useState(
    lesson.exercise?.placeholder ?? "",
  );
  const [rubric, setRubric] = useState(
    lesson.exercise?.rubric.join("\n") ?? "",
  );

  useEffect(() => {
    setTitle(lesson.title);
    setSummary(lesson.summary);
    setReading(lesson.reading);
    setObjectives(lesson.objectives.join("\n"));
    setHasQuestion(Boolean(lesson.exercise));
    setPrompt(lesson.exercise?.prompt ?? "");
    setPlaceholder(lesson.exercise?.placeholder ?? "");
    setRubric(lesson.exercise?.rubric.join("\n") ?? "");
  }, [lesson]);
  if (!module) return null;

  const save = () =>
    mutate(
      {
        ...operationBase(snapshot),
        type: "lesson.update",
        moduleId: module.id,
        lesson: {
          ...lesson,
          title: title.trim(),
          summary,
          reading,
          objectives: objectives
            .split("\n")
            .map((value) => value.trim())
            .filter(Boolean)
            .slice(0, 16),
          ...(hasQuestion
            ? {
                exercise: {
                  id:
                    lesson.exercise?.id ??
                    `exercise_${crypto.randomUUID().replaceAll("-", "")}`,
                  prompt: prompt.trim(),
                  ...(placeholder.trim()
                    ? { placeholder: placeholder.trim() }
                    : {}),
                  rubric: rubric
                    .split("\n")
                    .map((value) => value.trim())
                    .filter(Boolean)
                    .slice(0, 12),
                },
              }
            : { exercise: undefined }),
        },
      },
      `lesson-edit-${lesson.id}`,
    );

  return (
    <details
      open
      className={css({ border: "1px solid var(--ink)", bg: "var(--card)" })}
    >
      <summary
        className={css({
          cursor: "pointer",
          px: "0.65rem",
          py: "0.55rem",
          fontSize: "0.78rem",
          fontWeight: 750,
        })}
      >
        Edit current lesson
      </summary>
      <div
        className={css({
          display: "grid",
          gap: "0.45rem",
          borderTop: "1px solid var(--ink)",
          p: "0.65rem",
        })}
      >
        <input
          value={title}
          maxLength={240}
          onChange={(event) => setTitle(event.target.value)}
          className={inputClass}
          aria-label="Lesson title"
        />
        <textarea
          value={summary}
          maxLength={2_000}
          onChange={(event) => setSummary(event.target.value)}
          className={inputClass}
          rows={2}
          placeholder="Lesson summary"
        />
        <textarea
          value={reading}
          maxLength={120_000}
          onChange={(event) => setReading(event.target.value)}
          className={inputClass}
          rows={7}
          placeholder="Lesson reading, examples, or instructions"
        />
        <textarea
          value={objectives}
          onChange={(event) => setObjectives(event.target.value)}
          className={inputClass}
          rows={3}
          placeholder="One objective per line"
        />
        <div
          className={css({
            mt: "0.2rem",
            border: "1px solid var(--ink)",
            bg: "var(--paper)",
            p: "0.6rem",
          })}
        >
          <div
            className={css({
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "0.5rem",
            })}
          >
            <span
              className={css({
                display: "inline-flex",
                alignItems: "center",
                gap: "0.35rem",
                fontSize: "0.75rem",
                fontWeight: 750,
              })}
            >
              <FileQuestion size={14} /> Practice question
            </span>
            <button
              type="button"
              className={buttonClass}
              onClick={() => setHasQuestion((value) => !value)}
            >
              {hasQuestion ? "Remove question" : "Add question"}
            </button>
          </div>
          {hasQuestion ? (
            <div
              className={css({ mt: "0.55rem", display: "grid", gap: "0.4rem" })}
            >
              <textarea
                value={prompt}
                maxLength={30_000}
                onChange={(event) => setPrompt(event.target.value)}
                className={inputClass}
                rows={4}
                placeholder="Question or exercise prompt"
              />
              <input
                value={placeholder}
                maxLength={240}
                onChange={(event) => setPlaceholder(event.target.value)}
                className={inputClass}
                placeholder="Answer field hint (optional)"
              />
              <textarea
                value={rubric}
                onChange={(event) => setRubric(event.target.value)}
                className={inputClass}
                rows={3}
                placeholder="One rubric point per line"
              />
            </div>
          ) : (
            <p
              className={css({
                mt: "0.4rem",
                fontSize: "0.7rem",
                color: "var(--ink-soft)",
              })}
            >
              This lesson has no question. Add one when practice belongs here.
            </p>
          )}
        </div>
        <div
          className={css({
            display: "flex",
            justifyContent: "space-between",
            gap: "0.4rem",
          })}
        >
          <button
            type="button"
            className={buttonClass}
            disabled={
              !title.trim() ||
              (hasQuestion && !prompt.trim()) ||
              saving === `lesson-edit-${lesson.id}`
            }
            onClick={() => void save()}
          >
            <Save size={12} /> Save lesson
          </button>
          <button
            type="button"
            className={cx(buttonClass, css({ color: "var(--destructive)" }))}
            onClick={() => {
              if (confirmRemoval(`Remove “${lesson.title}”?`))
                void mutate(
                  {
                    ...operationBase(snapshot),
                    type: "lesson.delete",
                    moduleId: module.id,
                    lessonId: lesson.id,
                  },
                  `lesson-delete-${lesson.id}`,
                );
            }}
          >
            <Trash2 size={12} /> Remove
          </button>
        </div>
      </div>
    </details>
  );
}

function CardEditor({
  snapshot,
  card,
  saving,
  mutate,
}: {
  snapshot: CourseViewerSnapshot;
  card: CourseCard;
  saving: string;
  mutate: Mutate;
}) {
  const lessons = snapshot.course.modules.flatMap((module) => module.lessons);
  const [front, setFront] = useState(card.front);
  const [back, setBack] = useState(card.back);
  const [tags, setTags] = useState(card.tags.join(", "));
  const [lessonId, setLessonId] = useState(card.lessonId ?? "");
  useEffect(() => {
    setFront(card.front);
    setBack(card.back);
    setTags(card.tags.join(", "));
    setLessonId(card.lessonId ?? "");
  }, [card]);
  return (
    <details
      className={css({ border: "1px solid var(--ink)", bg: "var(--card)" })}
    >
      <summary
        className={css({
          cursor: "pointer",
          overflow: "hidden",
          textOverflow: "ellipsis",
          whiteSpace: "nowrap",
          px: "0.6rem",
          py: "0.5rem",
          fontSize: "0.72rem",
        })}
      >
        {card.front}
      </summary>
      <div
        className={css({
          display: "grid",
          gap: "0.4rem",
          borderTop: "1px solid var(--ink)",
          p: "0.6rem",
        })}
      >
        <textarea
          value={front}
          onChange={(event) => setFront(event.target.value)}
          className={inputClass}
          rows={2}
          placeholder="Front"
        />
        <textarea
          value={back}
          onChange={(event) => setBack(event.target.value)}
          className={inputClass}
          rows={3}
          placeholder="Back"
        />
        <input
          value={tags}
          onChange={(event) => setTags(event.target.value)}
          className={inputClass}
          placeholder="tags, separated, by commas"
        />
        <select
          value={lessonId}
          onChange={(event) => setLessonId(event.target.value)}
          className={inputClass}
          aria-label="Attach card to lesson"
        >
          <option value="">Course-wide card</option>
          {lessons.map((lesson) => (
            <option key={lesson.id} value={lesson.id}>
              {lesson.title}
            </option>
          ))}
        </select>
        <div
          className={css({
            display: "flex",
            justifyContent: "space-between",
            gap: "0.4rem",
          })}
        >
          <button
            type="button"
            className={buttonClass}
            disabled={
              !front.trim() || !back.trim() || saving === `card-${card.id}`
            }
            onClick={() =>
              void mutate(
                {
                  ...operationBase(snapshot),
                  type: "card.upsert",
                  card: {
                    id: card.id,
                    front: front.trim(),
                    back: back.trim(),
                    tags: tags
                      .split(",")
                      .map((tag) => tag.trim())
                      .filter(Boolean)
                      .slice(0, 24),
                    ...(lessonId ? { lessonId } : {}),
                  },
                },
                `card-${card.id}`,
              )
            }
          >
            <Save size={12} /> Save
          </button>
          <button
            type="button"
            className={cx(buttonClass, css({ color: "var(--destructive)" }))}
            onClick={() => {
              if (confirmRemoval("Remove this card?"))
                void mutate(
                  {
                    ...operationBase(snapshot),
                    type: "card.delete",
                    cardId: card.id,
                  },
                  `card-delete-${card.id}`,
                );
            }}
          >
            <Trash2 size={12} /> Remove
          </button>
        </div>
      </div>
    </details>
  );
}

function DeckManager({
  snapshot,
  activeLesson,
  saving,
  mutate,
}: {
  snapshot: CourseViewerSnapshot;
  activeLesson?: CourseLesson;
  saving: string;
  mutate: Mutate;
}) {
  const [front, setFront] = useState("");
  const [back, setBack] = useState("");
  const [decks, setDecks] = useState<FlashcardDeck[]>([]);
  const [deckId, setDeckId] = useState("");
  const [attachImported, setAttachImported] = useState(Boolean(activeLesson));
  useEffect(() => {
    let cancelled = false;
    void getInitPromise()
      .then(() => keatingStorage.getDecks())
      .then((items) => {
        if (!cancelled) setDecks(items);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, []);
  const addCard = async () => {
    if (!front.trim() || !back.trim()) return;
    await mutate(
      {
        ...operationBase(snapshot),
        type: "card.upsert",
        card: {
          id: `card_${crypto.randomUUID().replaceAll("-", "")}`,
          front: front.trim(),
          back: back.trim(),
          tags: [],
          ...(activeLesson ? { lessonId: activeLesson.id } : {}),
        },
      },
      "card-add",
    );
    setFront("");
    setBack("");
  };
  const importDeck = () => {
    const deck = decks.find((candidate) => candidate.id === deckId);
    if (!deck) return;
    const cards = assembleCourseInput({ decks: [deck] }).cards.map((card) => ({
      ...card,
      id: `card_${crypto.randomUUID().replaceAll("-", "")}`,
      ...(attachImported && activeLesson ? { lessonId: activeLesson.id } : {}),
    }));
    void mutate(
      { ...operationBase(snapshot), type: "cards.import", cards },
      `deck-import-${deck.id}`,
    );
  };
  return (
    <div className={css({ display: "grid", gap: "0.55rem" })}>
      <div
        className={css({
          display: "grid",
          gap: "0.4rem",
          border: "1px solid var(--ink)",
          bg: "var(--paper)",
          p: "0.6rem",
        })}
      >
        <textarea
          value={front}
          onChange={(event) => setFront(event.target.value)}
          className={inputClass}
          rows={2}
          placeholder="New card front"
        />
        <textarea
          value={back}
          onChange={(event) => setBack(event.target.value)}
          className={inputClass}
          rows={2}
          placeholder="New card back"
        />
        <button
          type="button"
          className={buttonClass}
          disabled={!front.trim() || !back.trim() || saving === "card-add"}
          onClick={() => void addCard()}
        >
          <Plus size={12} /> Add card{activeLesson ? " to lesson" : ""}
        </button>
      </div>
      {decks.length ? (
        <div
          className={css({
            display: "grid",
            gap: "0.4rem",
            border: "1px solid var(--ink)",
            bg: "var(--paper)",
            p: "0.6rem",
          })}
        >
          <select
            value={deckId}
            onChange={(event) => setDeckId(event.target.value)}
            className={inputClass}
          >
            <option value="">Choose a saved deck…</option>
            {decks.map((deck) => (
              <option key={deck.id} value={deck.id}>
                {deck.title} ({deck.cards.length})
              </option>
            ))}
          </select>
          {activeLesson ? (
            <label
              className={css({
                display: "inline-flex",
                alignItems: "center",
                gap: "0.4rem",
                fontSize: "0.7rem",
              })}
            >
              <input
                type="checkbox"
                checked={attachImported}
                onChange={(event) => setAttachImported(event.target.checked)}
              />{" "}
              Attach imported cards to this lesson
            </label>
          ) : null}
          <button
            type="button"
            className={buttonClass}
            disabled={!deckId || saving.startsWith("deck-import-")}
            onClick={importDeck}
          >
            <Upload size={12} /> Import deck
          </button>
        </div>
      ) : (
        <p className={css({ fontSize: "0.7rem", color: "var(--ink-soft)" })}>
          No saved decks yet. New cards can still be created here.
        </p>
      )}
      {snapshot.course.cards.length ? (
        <div className={css({ display: "grid", gap: "0.4rem" })}>
          {snapshot.course.cards.map((card) => (
            <CardEditor
              key={card.id}
              snapshot={snapshot}
              card={card}
              saving={saving}
              mutate={mutate}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function CourseAssemblyTools({
  snapshot,
  activeLesson,
  saving,
  mutate,
  onSnapshot,
  expanded = false,
}: {
  snapshot: CourseViewerSnapshot;
  activeLesson?: CourseLesson;
  saving: string;
  mutate: Mutate;
  onSnapshot(snapshot: CourseViewerSnapshot): void;
  expanded?: boolean;
}) {
  const [moduleTitle, setModuleTitle] = useState("");
  const canStructure = snapshot.permissions.canEditCourse;
  const canCards = snapshot.permissions.canEditDeck;
  const lessonCount = useMemo(
    () =>
      snapshot.course.modules.reduce(
        (count, module) => count + module.lessons.length,
        0,
      ),
    [snapshot.course.modules],
  );
  if (!canStructure && !canCards) return null;
  const addModule = async () => {
    if (!moduleTitle.trim()) return;
    await mutate(
      {
        ...operationBase(snapshot),
        type: "module.upsert",
        module: {
          id: `module_${crypto.randomUUID().replaceAll("-", "")}`,
          title: moduleTitle.trim(),
          description: "",
          lessons: [],
        },
      },
      "module-add",
    );
    setModuleTitle("");
  };
  return (
    <section
      className={
        expanded
          ? css({
              border: "2px solid var(--ink)",
              bg: "var(--paper-deep, #e9e2d2)",
              p: { base: "1rem", md: "1.25rem" },
            })
          : sectionClass
      }
    >
      <p className={labelClass}>Assemble course</p>
      <p
        className={css({
          mt: "0.25rem",
          fontSize: "0.72rem",
          color: "var(--ink-soft)",
          lineHeight: 1.45,
        })}
      >
        {snapshot.course.modules.length} modules · {lessonCount} lessons ·{" "}
        {snapshot.course.assignments.length} assignments ·{" "}
        {snapshot.course.artifacts.length} artifacts ·{" "}
        {snapshot.course.cards.length} cards
      </p>
      {canStructure ? (
        <>
          <div
            className={css({
              mt: "0.65rem",
              display: "flex",
              alignItems: "stretch",
              gap: "0.35rem",
            })}
          >
            <input
              value={moduleTitle}
              maxLength={240}
              onChange={(event) => setModuleTitle(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") void addModule();
              }}
              className={inputClass}
              placeholder="New module title"
            />
            <button
              type="button"
              className={buttonClass}
              disabled={!moduleTitle.trim() || saving === "module-add"}
              onClick={() => void addModule()}
            >
              <Plus size={12} /> Module
            </button>
          </div>
          <div
            className={css({ mt: "0.55rem", display: "grid", gap: "0.4rem" })}
          >
            {snapshot.course.modules.map((module) => (
              <ModuleEditor
                key={module.id}
                snapshot={snapshot}
                module={module}
                saving={saving}
                mutate={mutate}
              />
            ))}
          </div>
          {activeLesson ? (
            <div className={sectionClass}>
              <LessonEditor
                snapshot={snapshot}
                lesson={activeLesson}
                saving={saving}
                mutate={mutate}
              />
            </div>
          ) : null}
        </>
      ) : null}
      {canStructure ? (
        <div className={sectionClass}>
          <p
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              mb: "0.55rem",
              fontSize: "0.78rem",
              fontWeight: 750,
            })}
          >
            <BookUp size={14} /> Long-range assignments
          </p>
          <AssignmentManager
            snapshot={snapshot}
            activeLessonId={activeLesson?.id}
            saving={saving}
            mutate={mutate}
          />
        </div>
      ) : null}
      {canStructure ? (
        <div className={sectionClass}>
          <p
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              mb: "0.55rem",
              fontSize: "0.78rem",
              fontWeight: 750,
            })}
          >
            <Shapes size={14} /> Quizzes, GenUI, visuals, and artifacts
          </p>
          <ArtifactManager
            snapshot={snapshot}
            activeLessonId={activeLesson?.id}
            saving={saving}
            mutate={mutate}
          />
        </div>
      ) : null}
      {canStructure ? (
        <div className={sectionClass}>
          <p
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              mb: "0.55rem",
              fontSize: "0.78rem",
              fontWeight: 750,
            })}
          >
            <FilePlus2 size={14} /> Documents, images, and sources
          </p>
          <MaterialManager
            snapshot={snapshot}
            activeLessonId={activeLesson?.id}
            onSnapshot={onSnapshot}
          />
        </div>
      ) : null}
      {canCards ? (
        <div className={sectionClass}>
          <p
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              mb: "0.55rem",
              fontSize: "0.78rem",
              fontWeight: 750,
            })}
          >
            <CreditCard size={14} /> Cards and imports
          </p>
          <DeckManager
            snapshot={snapshot}
            activeLesson={activeLesson}
            saving={saving}
            mutate={mutate}
          />
        </div>
      ) : null}
      {!snapshot.course.modules.length && canStructure ? (
        <div
          className={css({
            mt: "0.8rem",
            borderLeft: "3px solid var(--course-green)",
            bg: "var(--course-wash, #ddebdd)",
            p: "0.7rem",
          })}
        >
          <p
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.35rem",
              fontSize: "0.74rem",
              fontWeight: 750,
            })}
          >
            <Layers3 size={14} /> A blank course is valid.
          </p>
          <p
            className={css({
              mt: "0.25rem",
              fontSize: "0.7rem",
              color: "var(--ink-soft)",
            })}
          >
            Add a module when the outline is ready. Nothing is inserted for you.
          </p>
        </div>
      ) : null}
    </section>
  );
}

