13	
14	export class CourseAuthorizationError extends Error {
15	  readonly code = "course_forbidden";
16	}
17	
18	export class CourseConflictError extends Error {
19	  readonly code = "course_conflict";
20	  constructor(
21	    message: string,
22	    readonly currentRevision: number,
23	  ) {
24	    super(message);
25	  }
26	}
