30	}
31	
32	function memberFor(course: Course, accountId: string): CourseMember {
33	  const member = course.members.find(
34	    (candidate) => candidate.accountId === accountId,
35	  );
36	  if (!member)
37	    throw new CourseAuthorizationError("You are not enrolled in this course.");
38	  return member;
39	}
40	
41	function roleCanTeach(role: CourseRole): boolean {
42	  return role === "owner" || role === "teacher";
43	}
44	
45	function roleCanOwn(role: CourseRole): boolean {
46	  return role === "owner";
47	}
48	
49	function assertLesson(course: Course, lessonId: string): void {
50	  if (!allCourseLessons(course).some((lesson) => lesson.id === lessonId)) {
51	    throw new CourseNotFoundError(
52	      "This lesson is no longer part of the course.",
53	    );
54	  }
55	}
56	
57	function assertAssignment(course: Course, assignmentId: string): void {
58	  if (
59	    !course.assignments.some((assignment) => assignment.id === assignmentId)
60	  ) {
61	    throw new CourseNotFoundError(
62	      "This assignment is no longer part of the course.",
63	    );
64	  }
65	}
66	
67	function activity(
68	  id: string,
69	  type: CourseActivity["type"],
70	  accountId: string,
71	  message: string,
72	  createdAt: string,
73	  lessonId?: string,
74	): CourseActivity {
75	  return {
76	    // Operation ids are stable across storage replays and Pear replication.
77	    id,
78	    type,
79	    accountId,
80	    message,
81	    createdAt,
82	    ...(lessonId ? { lessonId } : {}),
83	  };
84	}
85	
86	function appendActivity(course: Course, item: CourseActivity): void {
87	  course.activity = [item, ...course.activity].slice(0, 5_000);
88	}
89	
90	function operationNeedsCurrentRevision(operation: CourseOperation): boolean {
91	  return (
92	    operation.type === "course.update" ||
93	    operation.type === "module.upsert" ||
94	    operation.type === "module.delete" ||
95	    operation.type === "lesson.update" ||
96	    operation.type === "lesson.delete" ||
97	    operation.type === "card.upsert" ||
98	    operation.type === "cards.import" ||
99	    operation.type === "card.delete" ||
100	    operation.type === "artifact.upsert" ||
101	    operation.type === "artifacts.import" ||
102	    operation.type === "artifact.delete" ||
103	    operation.type === "assignment.upsert" ||
104	    operation.type === "assignment.delete" ||
105	    operation.type === "material.add" ||
106	    operation.type === "material.delete" ||
107	    operation.type === "member.role.update"
108	  );
109	}
110	
111	function removeLessonState(
112	  course: Course,
113	  lessonIds: ReadonlySet<string>,
114	): void {
115	  for (const member of course.members) {
116	    member.progress.completedLessonIds =
117	      member.progress.completedLessonIds.filter((id) => !lessonIds.has(id));
118	    if (
119	      member.progress.activeLessonId &&
120	      lessonIds.has(member.progress.activeLessonId)
121	    ) {
122	      delete member.progress.activeLessonId;
123	    }
124	  }
125	  course.sharedNotes = course.sharedNotes.filter(
126	    (note) => !lessonIds.has(note.lessonId),
127	  );
128	  course.submissions = course.submissions.filter(
129	    (submission) => !lessonIds.has(submission.lessonId),
130	  );
131	  course.comments = course.comments.filter(
132	    (comment) => !lessonIds.has(comment.lessonId),
133	  );
134	  course.cards = course.cards.map((card) =>
135	    card.lessonId && lessonIds.has(card.lessonId)
136	      ? (() => {
137	          const { lessonId: _lessonId, ...unlinked } = card;
138	          return unlinked;
139	        })()
140	      : card,
141	  );
142	  course.artifacts = course.artifacts.map((artifact) =>
143	    artifact.lessonId && lessonIds.has(artifact.lessonId)
144	      ? (() => {
145	          const { lessonId: _lessonId, ...unlinked } = artifact;
146	          return unlinked;
147	        })()
148	      : artifact,
149	  );
150	  course.materials = course.materials.map((material) =>
151	    material.lessonId && lessonIds.has(material.lessonId)
152	      ? (() => {
153	          const { lessonId: _lessonId, ...unlinked } = material;
154	          return unlinked;
155	        })()
156	      : material,
157	  );
158	  course.assignments = course.assignments.map((assignment) =>
159	    assignment.lessonId && lessonIds.has(assignment.lessonId)
160	      ? (() => {
161	          const { lessonId: _lessonId, ...unlinked } = assignment;
162	          return unlinked;
163	        })()
164	      : assignment,
165	  );
166	}
167	
168	function removeCardReferences(course: Course, cardId: string): void {
169	  for (const module of course.modules) {
170	    for (const lesson of module.lessons) {
171	      lesson.cardIds = lesson.cardIds.filter((id) => id !== cardId);
172	    }
173	  }
174	}
175	
176	function removeMaterialReferences(course: Course, materialId: string): void {
177	  for (const module of course.modules) {
178	    for (const lesson of module.lessons) {
179	      lesson.materialIds = lesson.materialIds.filter((id) => id !== materialId);
180	    }
181	  }
182	}
183	
184	export function permissionsFor(
185	  course: Course,
186	  accountId: string,
187	): CoursePermissions {
188	  const member = memberFor(course, accountId);
189	  const canTeach = roleCanTeach(member.role);
190	  return {
191	    canEditCourse: canTeach,
192	    canInvite: canTeach,
193	    canReview: canTeach,
194	    canEditDeck: canTeach || course.settings.allowPeerDeckEdits,
195	    canRequestTeacherAccess: canTeach,
196	  };
197	}
198	
199	export function applyCourseOperation(
200	  current: Course,
201	  actorAccountId: string,
202	  operation: CourseOperation,
203	  now = new Date().toISOString(),
204	): Course {
205	  if (operation.courseId !== current.id) {
206	    throw new CourseNotFoundError("The operation targets a different course.");
207	  }
208	  if (
209	    operationNeedsCurrentRevision(operation) &&
210	    operation.baseRevision !== current.revision
211	  ) {
212	    throw new CourseConflictError(
213	      "The course changed while you were editing. Refresh and try again.",
214	      current.revision,
215	    );
216	  }
217	
218	  const actor = memberFor(current, actorAccountId);
219	  const next = structuredClone(current);
220	
221	  switch (operation.type) {
222	    case "course.update": {
223	      if (!roleCanTeach(actor.role)) {
224	        throw new CourseAuthorizationError(
225	          "Only course teachers can change course details.",
226	        );
227	      }
228	      Object.assign(next, operation.patch);
229	      break;
230	    }
231	    case "module.upsert": {
232	      if (!roleCanTeach(actor.role)) {
233	        throw new CourseAuthorizationError(
234	          "Only course teachers can edit modules.",
235	        );
236	      }
237	      const duplicateLesson = operation.module.lessons.find((lesson) =>
238	        next.modules.some(
239	          (module) =>
240	            module.id !== operation.module.id &&
241	            module.lessons.some((item) => item.id === lesson.id),
242	        ),
243	      );
244	      if (duplicateLesson) {
245	        throw new CourseConflictError(
246	          "A lesson with this id already exists in another module.",
247	          next.revision,
248	        );
249	      }
250	      const index = next.modules.findIndex(
251	        (module) => module.id === operation.module.id,
252	      );
253	      if (index === -1) next.modules.push(operation.module);
254	      else {
255	        const retainedIds = new Set(
256	          operation.module.lessons.map((lesson) => lesson.id),
257	        );
258	        const removedIds = new Set(
259	          next.modules[index]!.lessons.map((lesson) => lesson.id).filter(
260	            (id) => !retainedIds.has(id),
261	          ),
262	        );
263	        if (removedIds.size) removeLessonState(next, removedIds);
264	        next.modules[index] = operation.module;
265	      }
266	      appendActivity(
267	        next,
268	        activity(
269	          operation.id,
270	          "module-updated",
271	          actorAccountId,
272	          "Updated the course outline",
273	          now,
274	        ),
275	      );
276	      break;
277	    }
278	    case "module.delete": {
279	      if (!roleCanTeach(actor.role)) {
280	        throw new CourseAuthorizationError(
281	          "Only course teachers can remove modules.",
282	        );
283	      }
284	      const index = next.modules.findIndex(
285	        (module) => module.id === operation.moduleId,
286	      );
287	      if (index === -1)
288	        throw new CourseNotFoundError(
289	          "This module is no longer part of the course.",
290	        );
291	      const lessonIds = new Set(
292	        next.modules[index]!.lessons.map((lesson) => lesson.id),
293	      );
294	      next.modules.splice(index, 1);
295	      removeLessonState(next, lessonIds);
296	      appendActivity(
297	        next,
298	        activity(
299	          operation.id,
300	          "module-removed",
301	          actorAccountId,
302	          "Removed a course module",
303	          now,
304	        ),
305	      );
306	      break;
307	    }
308	    case "lesson.update": {
309	      if (!roleCanTeach(actor.role)) {
310	        throw new CourseAuthorizationError(
311	          "Only course teachers can edit lessons.",
312	        );
313	      }
314	      const module = next.modules.find(
315	        (candidate) => candidate.id === operation.moduleId,
316	      );
317	      if (!module)
318	        throw new CourseNotFoundError(
319	          "This module is no longer part of the course.",
320	        );
321	      if (
322	        next.modules.some(
323	          (candidate) =>
324	            candidate.id !== module.id &&
325	            candidate.lessons.some(
326	              (lesson) => lesson.id === operation.lesson.id,
327	            ),
328	        )
329	      ) {
330	        throw new CourseConflictError(
331	          "A lesson with this id already exists in another module.",
332	          next.revision,
333	        );
334	      }
335	      const index = module.lessons.findIndex(
336	        (lesson) => lesson.id === operation.lesson.id,
337	      );
338	      if (index === -1) module.lessons.push(operation.lesson);
339	      else module.lessons[index] = operation.lesson;
340	      appendActivity(
341	        next,
342	        activity(
343	          operation.id,
344	          "lesson-updated",
345	          actorAccountId,
346	          "Updated a course lesson",
347	          now,
348	          operation.lesson.id,
349	        ),
350	      );
351	      break;
352	    }
353	    case "lesson.delete": {
354	      if (!roleCanTeach(actor.role)) {
355	        throw new CourseAuthorizationError(
356	          "Only course teachers can remove lessons.",
357	        );
358	      }
359	      const module = next.modules.find(
360	        (candidate) => candidate.id === operation.moduleId,
361	      );
362	      if (!module)
363	        throw new CourseNotFoundError(
364	          "This module is no longer part of the course.",
365	        );
366	      const index = module.lessons.findIndex(
367	        (lesson) => lesson.id === operation.lessonId,
368	      );
369	      if (index === -1)
370	        throw new CourseNotFoundError(
371	          "This lesson is no longer part of the course.",
372	        );
373	      module.lessons.splice(index, 1);
374	      removeLessonState(next, new Set([operation.lessonId]));
375	      appendActivity(
376	        next,
377	        activity(
378	          operation.id,
379	          "lesson-removed",
380	          actorAccountId,
381	          "Removed a course lesson",
382	          now,
383	        ),
384	      );
385	      break;
386	    }
387	    case "lesson.complete": {
388	      assertLesson(next, operation.lessonId);
389	      const target = next.members.find(
390	        (member) => member.accountId === actorAccountId,
391	      )!;
392	      const completed = new Set(target.progress.completedLessonIds);
393	      if (operation.completed) completed.add(operation.lessonId);
394	      else completed.delete(operation.lessonId);
395	      target.progress.completedLessonIds = [...completed];
396	      target.progress.activeLessonId = operation.lessonId;
397	      target.progress.lastActiveAt = now;
398	      appendActivity(
399	        next,
400	        activity(
401	          operation.id,
402	          "lesson-completed",
403	          actorAccountId,
404	          operation.completed ? "Completed a lesson" : "Reopened a lesson",
405	          now,
406	          operation.lessonId,
407	        ),
408	      );
