1010	function canSeeSubmission(
1011	  course: Course,
1012	  viewer: CourseMember,
1013	  submission: CourseSubmission,
1014	): boolean {
1015	  if (submission.accountId === viewer.accountId) return true;
1016	  if (roleCanTeach(viewer.role)) {
1017	    return memberFor(course, submission.accountId).teacherAccess === "full";
1018	  }
1019	  return submission.sharedWithPeers;
1020	}
1021	
1022	function canSeeAssignmentSubmission(
1023	  course: Course,
1024	  viewer: CourseMember,
1025	  submission: CourseAssignmentSubmission,
1026	): boolean {
1027	  if (submission.accountId === viewer.accountId) return true;
1028	  if (roleCanTeach(viewer.role)) {
1029	    return memberFor(course, submission.accountId).teacherAccess === "full";
1030	  }
1031	  return submission.sharedWithPeers;
1032	}
1033	
1034	function canSeeMemberPrivateState(
1035	  viewer: CourseMember,
1036	  member: CourseMember,
1037	): boolean {
1038	  if (member.accountId === viewer.accountId) return true;
1039	  return (
1040	    roleCanTeach(viewer.role) &&
1041	    !roleCanTeach(member.role) &&
1042	    member.teacherAccess === "full"
1043	  );
1044	}
1045	
1046	function canSeeMemberConsentState(
1047	  viewer: CourseMember,
1048	  member: CourseMember,
1049	): boolean {
1050	  if (member.accountId === viewer.accountId) return true;
1051	  return roleCanTeach(viewer.role) && !roleCanTeach(member.role);
1052	}
1053	
1054	function projectMemberForViewer(
1055	  course: Course,
1056	  viewer: CourseMember,
1057	  member: CourseMember,
1058	): CourseMember {
1059	  if (canSeeMemberPrivateState(viewer, member)) return structuredClone(member);
1060	  return {
1061	    accountId: member.accountId,
1062	    displayName: member.displayName,
1063	    role: member.role,
1064	    teacherAccess: canSeeMemberConsentState(viewer, member)
1065	      ? member.teacherAccess
1066	      : "private",
1067	    // CourseMember remains schema-compatible without revealing member-specific timestamps.
1068	    joinedAt: course.createdAt,
1069	    progress: {
1070	      completedLessonIds: [],
1071	      lastActiveAt: course.createdAt,
1072	    },
1073	  };
1074	}
1075	
1076	export function projectCourseForViewer(
1077	  course: Course,
1078	  viewerAccountId: string,
1079	): CourseViewerSnapshot {
1080	  const viewer = memberFor(course, viewerAccountId);
1081	  const projected = structuredClone(course);
1082	  projected.materials = projected.materials.map((material) => {
1083	    const { storageKey: _storageKey, ...publicMaterial } = material;
1084	    return publicMaterial;
1085	  });
1086	  projected.members = course.members.map((member) =>
1087	    projectMemberForViewer(course, viewer, member),
1088	  );
1089	  projected.submissions = projected.submissions.filter((submission) =>
1090	    canSeeSubmission(course, viewer, submission),
1091	  );
1092	  projected.assignmentSubmissions = projected.assignmentSubmissions.filter(
1093	    (submission) => canSeeAssignmentSubmission(course, viewer, submission),
1094	  );
1095	  projected.activity = projected.activity.filter((item) => {
1096	    const member = course.members.find(
1097	      (candidate) => candidate.accountId === item.accountId,
1098	    );
1099	    return member ? canSeeMemberPrivateState(viewer, member) : false;
1100	  });
1101	  return {
1102	    course: projected,
1103	    viewer: structuredClone(viewer),
1104	    permissions: permissionsFor(course, viewerAccountId),
1105	  };
1106	}
