346	      materialIds: existing?.materialIds ?? [],
347	      cardIds: existing?.cardIds ?? [],
348	      ...(exercisePrompt || existing?.exercise
349	        ? {
350	            exercise: {
351	              id: existing?.exercise?.id ?? courseId("exercise"),
352	              prompt:
353	                exercisePrompt ??
354	                existing?.exercise?.prompt ??
355	                "Apply what this lesson teaches.",
356	              ...((optionalText(params.exercise_placeholder) ??
357	              existing?.exercise?.placeholder)
358	                ? {
359	                    placeholder:
360	                      optionalText(params.exercise_placeholder) ??
361	                      existing?.exercise?.placeholder,
362	                  }
363	                : {}),
364	              rubric:
365	                params.rubric !== undefined
366	                  ? stringList(params.rubric)
367	                  : (existing?.exercise?.rubric ?? []),
368	            },
369	          }
370	        : {}),
371	    };
372	    return applyMutation(
373	      snapshot,
374	      { ...base, type: "lesson.update", moduleId, lesson },
375	      `${existing ? "Updated" : "Added"} lesson “${lesson.title}”.`,
376	    );
377	  }
