379	  if (action === "upsert_assignment") {
380	    const requestedId = optionalText(params.assignment_id);
381	    const existing = requestedId
382	      ? snapshot.course.assignments.find(
383	          (assignment) => assignment.id === requestedId,
384	        )
385	      : undefined;
386	    const title = optionalText(params.title) ?? existing?.title;
387	    const brief = optionalText(params.brief) ?? existing?.brief;
