389	      throw new Error("A title and brief are required for a new assignment.");
390	    }
391	    const assignment: Omit<CourseAssignment, "updatedAt" | "updatedBy"> = {
392	      id: existing?.id ?? requestedId ?? courseId("assignment"),
393	      title,
394	      brief,
395	      deliverables:
396	        params.deliverables !== undefined
397	          ? stringList(params.deliverables)
398	          : (existing?.deliverables ?? []),
399	      rubric:
400	        params.rubric !== undefined
401	          ? stringList(params.rubric)
402	          : (existing?.rubric ?? []),
403	      ...((optionalText(params.lesson_id) ?? existing?.lessonId)
404	        ? { lessonId: optionalText(params.lesson_id) ?? existing?.lessonId }
405	        : {}),
406	      ...((optionalText(params.due_at) ?? existing?.dueAt)
407	        ? { dueAt: optionalText(params.due_at) ?? existing?.dueAt }
408	        : {}),
409	      ...((positiveNumber(params.estimated_hours) ?? existing?.estimatedHours)
410	        ? {
411	            estimatedHours:
412	              positiveNumber(params.estimated_hours) ??
413	              existing?.estimatedHours,
414	          }
415	        : {}),
416	    };
417	    return applyMutation(
418	      snapshot,
419	      { ...base, type: "assignment.upsert", assignment },
420	      `${existing ? "Updated" : "Added"} assignment “${assignment.title}”.`,
421	    );
422	  }
423	
424	  if (action === "upsert_artifact") {
425	    const requestedId = optionalText(params.artifact_id);
426	    const existing = requestedId
427	      ? snapshot.course.artifacts.find(
428	          (artifact) => artifact.id === requestedId,
429	        )
430	      : undefined;
431	    const title = optionalText(params.title) ?? existing?.title;
432	    const content =
433	      params.content !== undefined ? String(params.content) : existing?.content;
434	    if (!title || !content) {
435	      throw new Error("A title and content are required for a new artifact.");
436	    }
437	    const kind = (optionalText(params.artifact_kind) ??
438	      existing?.kind ??
439	      "other") as CourseArtifactKind;
440	    const format = (optionalText(params.artifact_format) ??
441	      existing?.format ??
442	      "markdown") as CourseArtifactFormat;
443	    const artifact = {
444	      id: existing?.id ?? requestedId ?? courseId("artifact"),
445	      kind,
446	      format,
447	      title,
448	      ...((optionalText(params.description) ?? existing?.description)
449	        ? {
450	            description:
451	              optionalText(params.description) ?? existing?.description,
452	          }
453	        : {}),
454	      content,
455	      ...((optionalText(params.lesson_id) ?? existing?.lessonId)
456	        ? { lessonId: optionalText(params.lesson_id) ?? existing?.lessonId }
457	        : {}),
458	      ...(existing?.sourceId ? { sourceId: existing.sourceId } : {}),
459	      ...(existing?.sourceSessionId
460	        ? { sourceSessionId: existing.sourceSessionId }
461	        : {}),
462	    };
463	    return applyMutation(
464	      snapshot,
465	      { ...base, type: "artifact.upsert", artifact },
466	      `${existing ? "Updated" : "Added"} ${kind.replaceAll("-", " ")} “${artifact.title}”.`,
467	    );
468	  }
469	
470	  if (action === "upsert_card") {
471	    const requestedId = optionalText(params.card_id);
472	    const existing = requestedId
473	      ? snapshot.course.cards.find((card) => card.id === requestedId)
474	      : undefined;
475	    const front = optionalText(params.front) ?? existing?.front;
476	    const back = optionalText(params.back) ?? existing?.back;
