481	      id: existing?.id ?? requestedId ?? courseId("card"),
482	      front,
483	      back,
484	      tags:
485	        params.tags !== undefined
486	          ? stringList(params.tags)
487	          : (existing?.tags ?? []),
488	      ...((optionalText(params.lesson_id) ?? existing?.lessonId)
489	        ? { lessonId: optionalText(params.lesson_id) ?? existing?.lessonId }
490	        : {}),
491	    };
492	    return applyMutation(
493	      snapshot,
494	      { ...base, type: "card.upsert", card },
495	      `${existing ? "Updated" : "Added"} a flashcard.`,
496	    );
497	  }
498	
499	  throw new Error(`Unsupported course action: ${action || "missing action"}.`);
500	}
