703	    ? `The active course is \`${course.activeCourseId}\`. Use it by default and inspect it before proposing edits.`
704	    : course?.mode === "create"
705	      ? "The learner opened chat from the new-course flow. Begin by shaping a course together."
706	      : "Course tools are available whenever the learner wants to create or revise a course.";
707	  return `${COURSE_PROMPT_START}
708	## Course collaboration
709	
710	${active}
711	
712	Treat course creation as a conversation, not a one-shot generation task. Establish the intended learners, current level, observable outcomes, pace or time constraints, and which existing plans or artifacts matter. Offer a compact outline and invite corrections before calling course_create, unless the learner explicitly asks you to create immediately. After creation, use course_inspect and make small, agreed changes with course_update so the learner can steer the structure. You can add modules, lessons, quizzes, other artifacts, assignments, and flashcards. Never claim a course changed unless the tool call succeeded, and always return the course link after a successful change.
713	${COURSE_PROMPT_END}`;
714	}
715	
716	export function appendCourseCollaborationPrompt(
717	  systemPrompt: string,
718	  course?: KeatingToolsOptions["course"],
719	): string {
720	  const start = systemPrompt.indexOf(COURSE_PROMPT_START);
721	  let base = systemPrompt;
722	  if (start >= 0) {
723	    const end = systemPrompt.indexOf(COURSE_PROMPT_END, start);
724	    base =
725	      end >= 0
726	        ? `${systemPrompt.slice(0, start)}${systemPrompt.slice(end + COURSE_PROMPT_END.length)}`
727	        : systemPrompt.slice(0, start);
728	  }
729	  return `${base.trimEnd()}\n\n${courseCollaborationPrompt(course)}`;
