                        >
                          Request access
                        </button>
                      ) : (
                        member.teacherAccess
                      )}
                    </td>
                    <td>{formatCourseRelative(member.progress.lastActiveAt)}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4}>No learners have joined yet.</td>
                </tr>
              )}
            </tbody>
          </table>
