import { useCallback, useEffect, useMemo, useReducer, useState } from "react";
import { Link, useParams } from "@tanstack/react-router";
import {
  ArrowLeft,
  BookUp,
  Check,
  Circle,
  CreditCard,
  ExternalLink,
  FileText,
  Hammer,
  Image as ImageIcon,
  Layers3,
