} from "lucide-react";
import { css, cx } from "../../styled-system/css";
import {
  CourseAddMenu,
  CourseDocumentUploadButton,
} from "../components/courses/CourseAddMenu";
import { CourseArtifactCard } from "../components/courses/CourseArtifactCard";
import {
